import express from 'express';
import cors from 'cors';
import supertest from 'supertest';
import { v4 as uuidv4 } from 'uuid';

const app = express();
const PORT = 3000;

// In-memory store
let todos = [];

// Middleware
app.use(cors());
app.use(express.json());

// Helper: generate unique ID
const generateId = () => uuidv4();

// Helper: validate title
const validateTitle = (title) => {
  if (!title) return { valid: false, message: 'Title is required' };
  if (typeof title !== 'string') return { valid: false, message: 'Title must be a string' };
  if (title.length < 1 || title.length > 100) return { valid: false, message: 'Title must be 1-100 characters' };
  return { valid: true };
};

// GET /todos - list all todos with optional filter
app.get('/todos', (req, res) => {
  const { completed } = req.query;

  let filteredTodos = [...todos];

  if (completed !== undefined) {
    filteredTodos = filteredTodos.filter(todo => todo.completed === (completed === 'true'));
  }

  res.json(filteredTodos);
});

// GET /todos/:id - get single todo
app.get('/todos/:id', (req, res) => {
  const { id } = req.params;
  const todo = todos.find(t => t.id === id);

  if (!todo) {
    return res.status(404).json({ error: 'Todo not found' });
  }

  res.json(todo);
});

// POST /todos - create todo
app.post('/todos', (req, res) => {
  const { title } = req.body;

  const { valid, message } = validateTitle(title);
  if (!valid) {
    return res.status(400).json({ error: message });
  }

  const newTodo = {
    id: generateId(),
    title,
    completed: false,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString()
  };

  todos.push(newTodo);

  res.status(201).json(newTodo);
});

